#include "duration_cases.inc"
static void runSource(const char* source){put("/x.txt",source);start();trialDone();}
static uint32_t dwellOf(unsigned press=0){auto p=presses();check(p.size()>press,"press exists");size_t at=p[press];for(size_t i=at+1;i<lower::count;++i)if(lower::calls[i].bytes[2]==0)return uint32_t(lower::calls[i].at-lower::calls[at].at);check(false,"release exists");return 0;}
static void select(const char* mode){auto r=req();r.body["mode"]={mode};handleCapsTiming(&r,true);check(r.code==200,"authenticated timing selection");}
int main(int argc,char**argv){if(argc!=2)return 2;if(argv[1][0]!='M')return historical_duration_main(argc,argv);try{
 mscMock::reset();mock::reset();setup();check(startupControlledReady&&route_u::bindOwner(),"controlled owner");lower::reset();led_mock::nowUs=0;auto r=req();std::string id=argv[1];
 if(id=="M01"){check(route_u::selectedCapsTiming()==5,"boot default standard");runSource("CAPSLOCK\n");check(route_u::status().capsMs==5&&dwellOf()==6,"default scheduler unchanged");}
 else if(id=="M02"){select("mac");runSource("CAPSLOCK\n");check(route_u::status().capsMs==500&&dwellOf()>=500&&presses().size()==1,"ordinary caps extended once");}
 else if(id=="M03"){select("mac");runSource("STRING a\nENTER\n");check(dwellOf()==6&&dwellOf(1)==6,"other keys not slowed");}
 else if(id=="M04"){select("mac");runSource("SHIFT CAPSLOCK\nCTRL-CAPSLOCK\n");check(dwellOf()==6&&dwellOf(1)==6,"Caps chords not extended");}
 else if(id=="M05"){select("mac");runSource("CAPS\n");check(route_u::status().reason==route_u::Reason::Compiler&&lower::count==0,"no invented Caps alias");}
 else if(id=="M06"){for(const char* mode:{"","MAC","500","mac ","standardx"}){r.body["mode"]={mode};handleCapsTiming(&r,true);check(r.code==400&&route_u::selectedCapsTiming()==5,"exact finite mode strings");}check(!route_u::selectCapsTiming(100)&&!route_u::selectCapsTiming(0),"API bounds");}
 else if(id=="M07"){r.headers.clear();r.body["mode"]={"mac"};handleCapsTiming(&r,true);check(r.code==401&&route_u::selectedCapsTiming()==5,"unauth write rejected");handleCapsTiming(&r,false);check(r.code==401,"unauth observation rejected");}
 else if(id=="M08"){select("mac");put("/x.txt","DELAY 50\nCAPSLOCK\n");start();select("standard");trialDone();check(route_u::status().capsMs==500&&dwellOf()>=500&&route_u::selectedCapsTiming()==5,"immutable admission before owner starts");lower::reset();runSource("CAPSLOCK\n");check(dwellOf()==6,"future run uses new setting");}
 else if(id=="M09"){put("/x.txt","DELAY 50\nCAPSLOCK\n");start();select("mac");trialDone();check(route_u::status().capsMs==5&&dwellOf()==6,"active baseline not changed by selection");}
 else if(id=="M10"){select("mac");put("/x.txt","CAPSLOCK\n");r.query["engine"]={"routeb"};r.query["s"]={"x.txt"};handleRunScript(&r);check(r.code==202&&r.response.indexOf("\"effectiveCapsMs\":500")>=0,"admission evidence");handleStatus(&r);check(r.response.indexOf("\"routeBCapsMs\":500")>=0,"status snapshot setting");route_u::stop();trialDone();}
 else if(id=="M11"){select("mac");put("/x.txt","CAPSLOCK\n");start();trialPress();select("standard");check(route_u::status().capsMs==500,"dwell snapshot unchanged");trialDone();check(dwellOf()>=500,"no midpress shrink");}
 else if(id=="M12"){select("mac");check(route_u::requestCapsTrial(0)==route_u::Reply::Accepted,"diagnostic baseline");trialDone();check(dwellOf()==6&&route_u::status().capsMs==5&&route_u::selectedCapsTiming()==500,"diagnostic overrides selected ordinary mode");}
 else if(id=="M13"){select("standard");check(route_u::requestCapsTrial(250)==route_u::Reply::Accepted,"diagnostic duration");trialDone();check(dwellOf()>=250&&route_u::status().capsMs==250,"diagnostic retained");}
 else if(id=="M14"){select("mac");put("/x.txt","DELAY 5000\nCAPSLOCK\n");start();for(int i=0;i<300;++i)trialTick();handleStop(&r);trialDone();check(r.code==202&&presses().empty()&&!route_u::owned(),"STOP during focus delay before down");}
 else if(id=="M15"){select("mac");put("/x.txt","CAPSLOCK\n");start();for(int i=0;i<1000&&std::string(route_b::phase())!="Press";++i)trialTick();mock::usbReady=false;handleStop(&r);for(int i=0;i<10;++i)trialTick();check(presses().empty()&&route_u::owned(),"STOP before pending press no key, owner retained for cleanup");mock::usbReady=true;trialDone();check(!route_u::owned()&&route_u::status().reason==route_u::Reason::Cancelled,"cleanup completes");}
 else if(id=="M16"){select("mac");put("/x.txt","CAPSLOCK\nSTRING BAD\n");start();trialPress();auto at=mock::now;handleStop(&r);trialDone();check(route_u::status().reason==route_u::Reason::Cancelled&&!route_u::owned()&&mock::now-at<500&&presses().size()==1,"STOP during dwell immediate cooperative cleanup");}
 else if(id=="M17"){select("mac");put("/x.txt","CAPSLOCK\n");start();trialPress();for(int i=0;i<700&&std::string(route_b::phase())!="Release";++i)trialTick();mock::usbReady=false;handleStop(&r);for(int i=0;i<10;++i)trialTick();check(route_u::owned()&&route_u::requestStart("/x.txt")==route_u::Reply::Busy,"release backpressure holds owner");mock::usbReady=true;trialDone();check(!route_u::owned()&&presses().size()==1,"release after availability no replay");}
 else if(id=="M18"){select("mac");put("/x.txt","CAPSLOCK\n");start();trialPress();mock::now+=1001;trialTick();trialDone();check(route_u::status().reason==route_u::Reason::Deadline&&presses().size()==1,"bounded timeout");}
 else if(id=="M19"||id=="M20"){select("mac");put("/x.txt","CAPSLOCK\n");start();trialPress();if(id=="M19"){mock::usbMounted=false;tud_umount_cb();}else{mock::usbReady=false;tud_suspend_cb(false);}trialDone();auto n=lower::count;mock::usbMounted=mock::usbReady=true;tud_resume_cb();for(int i=0;i<100;++i)trialTick();check(route_u::status().reason!=route_u::Reason::Completed&&lower::count==n&&presses().size()==1,"loss/quarantine no reconnect replay");}
 else if(id=="M21"){select("mac");put("/x.txt","CAPSLOCK\n");start();for(int i=0;i<1000&&std::string(route_b::phase())!="Press";++i)trialTick();lower::next=lower::Outcome::FalseAfterPossibleAcceptance;trialTick();trialDone();auto n=lower::count;for(int i=0;i<100;++i)trialTick();check(route_u::status().phase==route_u::Phase::Quarantined&&lower::count==n,"ambiguous press not retried");}
 else if(id=="M22"){select("mac");put("/x.txt","CAPSLOCK\n");start();trialPress();route_u::stop();mock::usbReady=false;for(int i=0;i<10;++i)trialTick();handleStop(&r);check(r.code==202&&route_u::owned(),"STOP during cleanup stays bounded");mock::usbReady=true;trialDone();check(!route_u::owned()&&presses().size()==1,"cleanup terminal no repeat");}
 else if(id=="M23"){select("mac");put("/x.txt","CAPSLOCK\n");start();trialPress();route_u::Token t;check(!route_u::begin(route_u::Service::Files,t)&&route_u::requestStart("/x.txt")==route_u::Reply::Busy,"no early next owner");route_u::stop();trialDone();lower::reset();runSource("STRING a\n");auto n=lower::count;for(int i=0;i<1000;++i)trialTick();check(lower::count==n&&presses().size()==1,"cancelled Caps never releases future owner");}
 else if(id=="M24"){led_mock::nowUs=100;uint8_t mask=2;mockKeyboard->_onOutput(1,&mask,1);led_mock::nowUs=6000101;handleLedTest(&r,0);check(r.response.indexOf("\"caps\":null")>=0&&r.response.indexOf("\"lastKnownCaps\":true")>=0&&r.response.indexOf("\"reportAgeUs\":\"6000001\"")>=0&&r.response.indexOf("\"ledEvidenceValid\":false")>=0,"stale keeps last-known distinct");}
 else if(id=="M25"){handleLedTest(&r,0);check(r.response.indexOf("\"lastKnownCaps\":null")>=0&&r.response.indexOf("\"reportAgeUs\":null")>=0,"unknown never becomes off");}
 else if(id=="M26"){select("mac");runSource("VAR $x = 1\nFUNCTION t()\nRETURN $x+1\nEND_FUNCTION\nWHILE $x < 3\nIF t() >= 2 THEN\nCAPSLOCK\nEND_IF\n$x = $x + 1\nEND_WHILE\n");check(route_u::status().reason==route_u::Reason::Completed&&presses().size()==2&&dwellOf()>=500&&dwellOf(1)>=500,"existing functions/expressions/loops preserved");}
 else if(id=="M27"){select("mac");for(const char* source:{"WAIT_FOR_CAPS_ON\n","SAVE_HOST_KEYBOARD_LOCK_STATE\n","VAR $x = $_CAPSLOCK_ON\n"}){lower::reset();runSource(source);check(route_u::status().reason!=route_u::Reason::Completed&&lower::count==0,"Route B lock commands/internal registry not claimed supported");}}
 else if(id=="M28"){Holder h;r.body["mode"]={"mac"};handleCapsTiming(&r,true);check(r.code==409&&route_u::selectedCapsTiming()==5,"bounded contended auth not false success");}
 else if(id=="M29"){http_mock::sending=atSend;r.body["mode"]={"mac"};handleCapsTiming(&r,true);http_mock::sending=nullptr;check(r.code==200&&lockFreeAtSend,"response sent outside lock");}
 else if(id=="M30"){select("mac");auto n=lower::count;handleCapsTiming(&r,false);check(r.code==200&&r.response.indexOf("\"selectedMs\":500")>=0&&r.response.indexOf("RAM until reboot")>=0&&lower::count==n&&!route_u::owned(),"selection/refresh never executes");}
 else if(id=="M31"){select("mac");runSource("DELAY 5000\nSTRING capscheck123\nENTER\nCAPSLOCK\nDELAY 1000\nSTRING capscheck123\nENTER\nCAPSLOCK\nDELAY 1000\nSTRING capscheck123\nENTER\n");check(route_u::status().reason==route_u::Reason::Completed,"finite owner fixture succeeds locally");unsigned caps=0;for(size_t i:presses())if(lower::calls[i].bytes[2]==0x39)++caps;check(caps==2,"exactly two Caps presses, no host-case simulation claim");}
 else if(id=="M32"){select("mac");put("/x.txt","CAPSLOCK\n");start();mock::now=UINT32_MAX-300;trialPress();trialDone();check(route_u::status().reason==route_u::Reason::Completed&&dwellOf()>=500,"wrap-safe ordinary Caps dwell");}
 else check(false,"unknown case");std::cout<<"PASS "<<id<<" ("<<assertions<<" assertions)\n";return 0;
 }catch(const std::exception&e){std::cerr<<"FAIL "<<argv[1]<<": "<<e.what()<<" ("<<assertions<<")\n";return 1;}}
